import{_ as r}from"./chunks/image (123).JNe7WnKj.js";import{_ as a,o as e,c as o,a2 as n}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Why to Build with Tradeboard?","description":"","frontmatter":{},"headers":[],"relativePath":"why-to-build-with-openalgo.md","filePath":"why-to-build-with-openalgo.md"}'),d={name:"why-to-build-with-openalgo.md"};function s(i,t,l,h,g,c){return e(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="why-to-build-with-tradeboard" tabindex="-1">Why to Build with Tradeboard? <a class="header-anchor" href="#why-to-build-with-tradeboard" aria-label="Permalink to &quot;Why to Build with Tradeboard?&quot;">​</a></h1><p><em>&quot;Why should I use Tradeboard when I can just build my strategy directly on top of the broker&#39;s SDK or API?&quot;</em></p><p>It&#39;s a common question. Many start with broker SDKs because it feels quick, just wire your signals and send orders. But soon, the pain points show up:</p><ul><li>How do you monitor trades in real-time?</li><li>Where do you store and replay logs?</li><li>How do you test webhooks or strategies before going live?</li><li>How do you manage symbols, expiries, and contracts across brokers?</li><li>What happens when you want to switch from Broker A to Broker B?</li><li>Who builds the option chain, the Greeks, the payoff diagram, the scalping keys?</li></ul><p>That&#39;s when you realize the SDK is not enough.</p><p><strong>Tradeboard takes care of the heavy lifting.</strong></p><p>It&#39;s not just an API wrapper. It&#39;s a <strong>full-stack, open-source trading platform</strong> you run on your own machine: a complete trading desk, not only an execution layer.</p><figure><img src="'+r+`" alt=""><figcaption></figcaption></figure><hr><h3 id="at-a-glance" tabindex="-1">At a Glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a Glance&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>36 broker plugins</strong></td><td>34 securities brokers, Delta Exchange for crypto derivatives, and a Dhan sandbox plugin</td></tr><tr><td><strong>6 official SDKs</strong></td><td>Python, Node.js, Java, .NET, Go, Rust</td></tr><tr><td><strong>53 node types</strong></td><td>In the Flow visual strategy builder</td></tr><tr><td><strong>90+ indicators</strong></td><td>In the built-in charting terminal</td></tr><tr><td><strong>18 options tools</strong></td><td>Chain, Greeks, OI, max pain, vol surface, GEX and more</td></tr><tr><td><strong>100% open source</strong></td><td>AGPL-3.0, self-hosted, zero data collection</td></tr></tbody></table><hr><h3 id="trade-from-the-platform-itself" tabindex="-1">Trade From the Platform Itself <a class="header-anchor" href="#trade-from-the-platform-itself" aria-label="Permalink to &quot;Trade From the Platform Itself&quot;">​</a></h3><p>Earlier versions of Tradeboard were mostly a bridge between your strategy and your broker. That is no longer the whole story. Tradeboard now ships its own trading surfaces, so you can trade directly from it without any external charting package.</p><h4 id="chart-trading-terminal" tabindex="-1">Chart Trading Terminal <a class="header-anchor" href="#chart-trading-terminal" aria-label="Permalink to &quot;Chart Trading Terminal&quot;">​</a></h4><p>Fire and manage orders from the chart itself, on streaming broker WebSocket data, with <strong>90+ indicators</strong> available on real market data.</p><p>See <a href="./new-features/trading-terminal.html">Chart Trading Terminal</a>.</p><h4 id="scalping-terminal" tabindex="-1">Scalping Terminal <a class="header-anchor" href="#scalping-terminal" aria-label="Permalink to &quot;Scalping Terminal&quot;">​</a></h4><p>A keyboard-driven terminal built for speed: arrow keys fire CE and PE orders, <strong>F6 flattens every position</strong> and <strong>F7 cancels every pending order</strong>. There is also <strong>FastScalper</strong>, a separate lightweight desktop build in Rust and Tauri.</p><p>See <a href="./new-features/fast-scalper.html">Scalping Terminal</a>.</p><h4 id="options-analytics" tabindex="-1">Options Analytics <a class="header-anchor" href="#options-analytics" aria-label="Permalink to &quot;Options Analytics&quot;">​</a></h4><p>A full options desk is built in, with real-time Greeks and payoff diagrams:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Tool</th><th>Tool</th></tr></thead><tbody><tr><td>Strategy Builder</td><td>Strategy Portfolio</td><td>Option Chain</td></tr><tr><td>Option Greeks</td><td>OI Tracker and Range</td><td>Max Pain</td></tr><tr><td>Straddle Chart</td><td>Straddle PnL</td><td>OI Profile</td></tr><tr><td>Vol Surface</td><td>IV Smile</td><td>GEX Dashboard</td></tr><tr><td>Gamma Density</td><td>Futures Arbitrage Scanner</td><td>Portfolio Backtester</td></tr><tr><td>SIP Backtester</td><td></td><td></td></tr></tbody></table><h4 id="action-center" tabindex="-1">Action Center <a class="header-anchor" href="#action-center" aria-label="Permalink to &quot;Action Center&quot;">​</a></h4><p>Square off, cancel, and manage open exposure from one screen, with exchange-aligned auto square-off.</p><p>See <a href="./new-features/action-center.html">Action Center</a>.</p><hr><h3 id="what-makes-tradeboard-different" tabindex="-1">What Makes Tradeboard Different? <a class="header-anchor" href="#what-makes-tradeboard-different" aria-label="Permalink to &quot;What Makes Tradeboard Different?&quot;">​</a></h3><h4 id="strategy-management-and-hosting" tabindex="-1">Strategy Management and Hosting <a class="header-anchor" href="#strategy-management-and-hosting" aria-label="Permalink to &quot;Strategy Management and Hosting&quot;">​</a></h4><p>Host your <strong>Python strategies directly inside Tradeboard</strong>, alongside strategies from TradingView, Amibroker, ChartInk, MetaTrader, Excel, or custom webhooks. Start, pause, schedule, monitor, and analyze, all from a central control plane.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td><strong>Python Strategy Hosting</strong></td><td>Upload and run Python scripts with scheduling</td></tr><tr><td><strong>Flow Visual Builder</strong></td><td>Drag-and-drop canvas wiring 53 node types from triggers to indicators, conditions and orders</td></tr><tr><td><strong>Multi-Platform Support</strong></td><td>TradingView, Amibroker, ChartInk, Excel, and more</td></tr><tr><td><strong>Centralized Control</strong></td><td>Manage all strategies from one dashboard</td></tr><tr><td><strong>Process Isolation</strong></td><td>Hosted strategies run in separate processes</td></tr></tbody></table><p>See <a href="./new-features/python-strategy-hosting.html">Python Strategy Hosting</a> and <a href="./new-features/flow-visual-strategy-builder.html">Flow</a>.</p><h4 id="sandbox-testing-and-api-analyzer" tabindex="-1">Sandbox Testing and API Analyzer <a class="header-anchor" href="#sandbox-testing-and-api-analyzer" aria-label="Permalink to &quot;Sandbox Testing and API Analyzer&quot;">​</a></h4><p>The <strong>Analyzer Mode</strong> works like a local sandbox: test signals, APIs, and strategies with 1 crore default sandbox capital without sending simulated orders to the broker. Market prices can still come from broker data services.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Benefit</th></tr></thead><tbody><tr><td><strong>Sandbox Capital</strong></td><td>1 crore to test freely</td></tr><tr><td><strong>Real Market Prices</strong></td><td>Realistic simulation with live data</td></tr><tr><td><strong>Margin Calculations</strong></td><td>Actual margin requirements enforced</td></tr><tr><td><strong>Position Tracking</strong></td><td>Full position and holdings management</td></tr><tr><td><strong>Execution Isolation</strong></td><td>Sandbox orders stay in the sandbox store</td></tr></tbody></table><p>See <a href="./new-features/api-analyzer.html">API Analyzer</a>.</p><h4 id="historical-data-and-backtesting" tabindex="-1">Historical Data and Backtesting <a class="header-anchor" href="#historical-data-and-backtesting" aria-label="Permalink to &quot;Historical Data and Backtesting&quot;">​</a></h4><p><strong>Historify</strong> lets you download and store historical market data locally using DuckDB. Use this data for backtesting, analysis, or feeding into your strategy development workflow. A <strong>portfolio backtester</strong> and <strong>SIP backtester</strong> are built in.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td><strong>Bulk Downloads</strong></td><td>Download years of OHLCV data</td></tr><tr><td><strong>DuckDB Storage</strong></td><td>Efficient columnar storage</td></tr><tr><td><strong>Multiple Timeframes</strong></td><td>1-minute to daily data</td></tr><tr><td><strong>Export Options</strong></td><td>CSV, TXT, ZIP, or Parquet</td></tr></tbody></table><p>See <a href="./new-features/historify.html">Historify</a> and <a href="./new-features/portfolio-analytics.html">Portfolio Backtester and Analyzer</a>.</p><h4 id="multi-broker-multi-platform" tabindex="-1">Multi-Broker, Multi-Platform <a class="header-anchor" href="#multi-broker-multi-platform" aria-label="Permalink to &quot;Multi-Broker, Multi-Platform&quot;">​</a></h4><p>Tradeboard ships <strong>36 broker plugins</strong>: 34 securities brokers, Delta Exchange for crypto derivatives, and a Dhan sandbox plugin for paper trading. The securities plugins share normalized API and WebSocket interfaces, reducing broker-specific strategy code.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    Your Strategy Code                   │</span></span>
<span class="line"><span>│                       (Write Once)                      │</span></span>
<span class="line"><span>└────────────────────────────┬────────────────────────────┘</span></span>
<span class="line"><span>                             │</span></span>
<span class="line"><span>                             ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                   Tradeboard Unified API                  │</span></span>
<span class="line"><span>│         (Common Interface Across Broker Plugins)        │</span></span>
<span class="line"><span>└───┬─────────┬─────────┬─────────┬─────────┬─────────┬───┘</span></span>
<span class="line"><span>    │         │         │         │         │         │</span></span>
<span class="line"><span>    ▼         ▼         ▼         ▼         ▼         ▼</span></span>
<span class="line"><span>┌───────┐ ┌───────┐ ┌───────┐ ┌───────┐ ┌───────┐ ┌───────┐</span></span>
<span class="line"><span>│Zerodha│ │ Angel │ │ Dhan  │ │ Fyers │ │Upstox │ │ More  │</span></span>
<span class="line"><span>└───────┘ └───────┘ └───────┘ └───────┘ └───────┘ └───────┘</span></span></code></pre></div><p>See the full list under <a href="./connect-brokers/brokers/README.html">Brokers</a> and <a href="./crypto/exchanges/delta-exchange.html">Delta Exchange</a>.</p><h4 id="unified-symbol-and-contract-management" tabindex="-1">Unified Symbol and Contract Management <a class="header-anchor" href="#unified-symbol-and-contract-management" aria-label="Permalink to &quot;Unified Symbol and Contract Management&quot;">​</a></h4><p>With Tradeboard&#39;s <strong>Common Symbol Format</strong>, you don&#39;t have to worry about broker-specific quirks. Contracts, expiries, and lot sizes are maintained automatically.</p><table tabindex="0"><thead><tr><th>Broker</th><th>Their Format</th><th>Tradeboard Format</th></tr></thead><tbody><tr><td>Zerodha</td><td><code>SBIN</code></td><td><code>SBIN</code></td></tr><tr><td>Angel</td><td><code>SBIN-EQ</code></td><td><code>SBIN</code></td></tr><tr><td>Dhan</td><td><code>SBIN</code></td><td><code>SBIN</code></td></tr></tbody></table><p><strong>One Tradeboard symbol format, subject to each plugin&#39;s exchange coverage.</strong></p><hr><h3 id="speed-stability-and-control" tabindex="-1">Speed, Stability, and Control <a class="header-anchor" href="#speed-stability-and-control" aria-label="Permalink to &quot;Speed, Stability, and Control&quot;">​</a></h3><h4 id="performance-optimizations" tabindex="-1">Performance Optimizations <a class="header-anchor" href="#performance-optimizations" aria-label="Permalink to &quot;Performance Optimizations&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Feature</th><th>Impact</th></tr></thead><tbody><tr><td><strong>HTTPX Connection Pooling</strong></td><td>Reuses outbound connections to reduce setup overhead</td></tr><tr><td><strong>WebSocket Broadcast Layer</strong></td><td>One broker stream powers multiple strategies</td></tr><tr><td><strong>Symbol Caching</strong></td><td>Instant symbol lookups without repeated API calls</td></tr><tr><td><strong>Rate Limit Management</strong></td><td>Automatic throttling to stay within broker limits</td></tr></tbody></table><h4 id="real-time-monitoring" tabindex="-1">Real-Time Monitoring <a class="header-anchor" href="#real-time-monitoring" aria-label="Permalink to &quot;Real-Time Monitoring&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Latency Monitor</strong></td><td>Track order round-trip times</td></tr><tr><td><strong>Traffic Logs</strong></td><td>Request metadata, status, and duration history</td></tr><tr><td><strong>P&amp;L Tracker</strong></td><td>Real-time profit and loss visualization</td></tr><tr><td><strong>WebSocket Dashboard</strong></td><td>Monitor live data connections</td></tr></tbody></table><p>See <a href="./new-features/traffic-latency-monitor.html">Traffic/Latency Monitor</a> and <a href="./new-features/pnl-tracker.html">PNL Tracker</a>.</p><h4 id="notification-and-alerts" tabindex="-1">Notification and Alerts <a class="header-anchor" href="#notification-and-alerts" aria-label="Permalink to &quot;Notification and Alerts&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Channel</th><th>Capabilities</th></tr></thead><tbody><tr><td><strong>Telegram Bot</strong></td><td>Trade notifications, commands, alerts</td></tr><tr><td><strong>WhatsApp</strong></td><td>Trade notifications and bot commands</td></tr><tr><td><strong>WebSocket Updates</strong></td><td>Real-time order and position changes</td></tr><tr><td><strong>Dashboard Alerts</strong></td><td>Visual notifications in UI</td></tr></tbody></table><hr><h3 id="security-by-default" tabindex="-1">Security by Default <a class="header-anchor" href="#security-by-default" aria-label="Permalink to &quot;Security by Default&quot;">​</a></h3><p>Tradeboard is production-tested with enterprise-grade security:</p><table tabindex="0"><thead><tr><th>Security Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>CORS &amp; CSP Headers</strong></td><td>Cross-origin and content security policies</td></tr><tr><td><strong>CSRF Protection</strong></td><td>Token-based request validation</td></tr><tr><td><strong>Rate Limiting</strong></td><td>Per-endpoint request throttling</td></tr><tr><td><strong>Two-Factor Auth</strong></td><td>TOTP-based login security</td></tr><tr><td><strong>Session Management</strong></td><td>Secure session handling with timeouts</td></tr><tr><td><strong>Audit Trails</strong></td><td>Complete logging for compliance</td></tr><tr><td><strong>API Key Protection</strong></td><td>Argon2 hashing plus encrypted retrieval copy</td></tr><tr><td><strong>Process Isolation</strong></td><td>Hosted strategies run in separate processes</td></tr><tr><td><strong>Zero Data Collection</strong></td><td>Your code, your strategies, your data, on your machine</td></tr></tbody></table><p>Deploy locally, in <strong>Docker</strong>, or on cloud servers. Public deployments still require correct TLS, proxy, firewall, secret, and update configuration.</p><hr><h3 id="sdks-add-ins-and-ecosystem" tabindex="-1">SDKs, Add-ins, and Ecosystem <a class="header-anchor" href="#sdks-add-ins-and-ecosystem" aria-label="Permalink to &quot;SDKs, Add-ins, and Ecosystem&quot;">​</a></h3><h4 id="official-sdks" tabindex="-1">Official SDKs <a class="header-anchor" href="#official-sdks" aria-label="Permalink to &quot;Official SDKs&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Language</th><th>Documentation</th></tr></thead><tbody><tr><td><strong>Python</strong></td><td><a href="./trading-platform/python/README.html"><code>tradeboard</code> on PyPI</a></td></tr><tr><td><strong>Node.js</strong></td><td><a href="./trading-platform/nodejs.html">NodeJS</a></td></tr><tr><td><strong>Java</strong></td><td><a href="./trading-platform/java.html">Java</a></td></tr><tr><td><strong>.NET</strong></td><td><a href="./trading-platform/.net.html">.NET</a></td></tr><tr><td><strong>Go</strong></td><td><a href="./trading-platform/go.html">GO</a></td></tr><tr><td><strong>Rust</strong></td><td><a href="./trading-platform/rust.html">RUST</a></td></tr></tbody></table><p>The Python SDK also ships an indicator library and visualization helpers. See <a href="./trading-platform/python/indicators/README.html">Indicators</a>.</p><h4 id="platform-integrations" tabindex="-1">Platform Integrations <a class="header-anchor" href="#platform-integrations" aria-label="Permalink to &quot;Platform Integrations&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Platform</th><th>Integration Type</th></tr></thead><tbody><tr><td><a href="./trading-platform/tradingview.html"><strong>TradingView</strong></a></td><td>Webhooks</td></tr><tr><td><a href="./trading-platform/amibroker/README.html"><strong>Amibroker</strong></a></td><td>HTTP calls from AFL, with ready-made trading modules</td></tr><tr><td><a href="./trading-platform/chartink.html"><strong>ChartInk</strong></a></td><td>Scanner webhooks</td></tr><tr><td><a href="./trading-platform/gocharting.html"><strong>GoCharting</strong></a></td><td>Webhooks</td></tr><tr><td><a href="./trading-platform/metatrader-5/README.html"><strong>MetaTrader 5</strong></a></td><td>MQL5 library and Expert Advisors</td></tr><tr><td><a href="./trading-platform/excel.html"><strong>Excel</strong></a></td><td>Excel add-in with native worksheet functions and real-time streaming</td></tr><tr><td><a href="./trading-platform/google-spreadsheets.html"><strong>Google Sheets</strong></a></td><td>Apps Script</td></tr><tr><td><a href="./trading-platform/n8n.html"><strong>N8N</strong></a></td><td>Workflow automation nodes</td></tr><tr><td><a href="./trading-platform/telegram.html"><strong>Telegram</strong></a></td><td>Bot notifications and commands</td></tr><tr><td><a href="./trading-platform/whatsapp.html"><strong>WhatsApp</strong></a></td><td>Notifications and bot commands</td></tr><tr><td><a href="./trading-platform/chrome-extension.html"><strong>Chrome Extension</strong></a></td><td>Browser-based order entry</td></tr></tbody></table><h4 id="ai-and-agent-integration" tabindex="-1">AI and Agent Integration <a class="header-anchor" href="#ai-and-agent-integration" aria-label="Permalink to &quot;AI and Agent Integration&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Product</th><th>Description</th></tr></thead><tbody><tr><td><a href="./mcp/README.html"><strong>Tradeboard MCP</strong></a></td><td>Connect your Tradeboard account to Claude, Cursor, Windsurf, or ChatGPT</td></tr><tr><td><a href="./skills/README.html"><strong>Tradeboard Skills</strong></a></td><td>Indicator, execution, and backtesting skills with ready-made strategies across India, US, and crypto markets</td></tr></tbody></table><h4 id="deployment-options" tabindex="-1">Deployment Options <a class="header-anchor" href="#deployment-options" aria-label="Permalink to &quot;Deployment Options&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Option</th><th>Best For</th></tr></thead><tbody><tr><td><strong>Local</strong></td><td>Personal desktop trading</td></tr><tr><td><strong>Docker</strong></td><td>Clean, reproducible deployments</td></tr><tr><td><strong>Cloud Server</strong></td><td>24/7 automated trading</td></tr><tr><td><strong>VPS</strong></td><td>Low-latency remote access</td></tr></tbody></table><hr><h3 id="why-not-just-use-broker-apis-directly" tabindex="-1">Why Not Just Use Broker APIs Directly? <a class="header-anchor" href="#why-not-just-use-broker-apis-directly" aria-label="Permalink to &quot;Why Not Just Use Broker APIs Directly?&quot;">​</a></h3><p>With direct broker APIs, you&#39;d have to build:</p><table tabindex="0"><thead><tr><th>Component</th><th>What You&#39;d Build</th><th>Tradeboard Provides</th></tr></thead><tbody><tr><td><strong>Strategy Hosting</strong></td><td>Process management, scheduling</td><td>Built-in with Python hosting</td></tr><tr><td><strong>Visual Strategy Building</strong></td><td>Node editor, execution engine</td><td>Flow with 53 node types</td></tr><tr><td><strong>Testing Environment</strong></td><td>Sandbox, mock broker</td><td>Analyzer Mode with 1 crore capital</td></tr><tr><td><strong>Charting</strong></td><td>Charting library, indicator maths</td><td>Built-in terminal with 90+ indicators</td></tr><tr><td><strong>Options Analytics</strong></td><td>Chain, Greeks, payoff, OI, vol surface</td><td>18 options tools included</td></tr><tr><td><strong>Scalping Interface</strong></td><td>Hotkey handling, fast order path</td><td>Keyboard scalping terminal</td></tr><tr><td><strong>Symbol Management</strong></td><td>Expiry handling, contract mapping</td><td>Unified symbol format</td></tr><tr><td><strong>Historical Data</strong></td><td>Download, store, query</td><td>Historify with DuckDB</td></tr><tr><td><strong>Connection Pooling</strong></td><td>HTTP/WebSocket optimization</td><td>HTTPX with connection reuse</td></tr><tr><td><strong>Trade Dashboard</strong></td><td>React UI, real-time updates</td><td>Full React frontend included</td></tr><tr><td><strong>Log Storage</strong></td><td>Database, query interface</td><td>SQLite with traffic logs</td></tr><tr><td><strong>Latency Tracking</strong></td><td>Timing, metrics, alerts</td><td>Latency monitor built-in</td></tr><tr><td><strong>Multi-Broker Support</strong></td><td>N broker integrations</td><td>36 plugin directories</td></tr><tr><td><strong>Security Layer</strong></td><td>Auth, rate limiting, CSRF</td><td>Enterprise security included</td></tr><tr><td><strong>Notifications</strong></td><td>Telegram, WhatsApp, alerts</td><td>Both integrated</td></tr></tbody></table><p>Tradeboard ships with all this, <strong>pre-wired, tested, and open source</strong>.</p><hr><h3 id="open-source-freedom" tabindex="-1">Open Source Freedom <a class="header-anchor" href="#open-source-freedom" aria-label="Permalink to &quot;Open Source Freedom&quot;">​</a></h3><p>Licensed under <strong>AGPL-3.0</strong>, Tradeboard gives you:</p><table tabindex="0"><thead><tr><th>Freedom</th><th>Description</th></tr></thead><tbody><tr><td><strong>Full Source Code</strong></td><td>Inspect, modify, extend</td></tr><tr><td><strong>Self-Hosting</strong></td><td>Run on your infrastructure</td></tr><tr><td><strong>No Tradeboard Per-Order Fees</strong></td><td>Broker and exchange charges still apply</td></tr><tr><td><strong>No Vendor Lock-in</strong></td><td>Switch or fork anytime</td></tr><tr><td><strong>Commercial Use</strong></td><td>Build products on top (with compliance)</td></tr><tr><td><strong>Community Support</strong></td><td>Discord, GitHub, documentation</td></tr></tbody></table><hr><h3 id="the-bottom-line" tabindex="-1">The Bottom Line <a class="header-anchor" href="#the-bottom-line" aria-label="Permalink to &quot;The Bottom Line&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Broker APIs</th><th>Tradeboard</th></tr></thead><tbody><tr><td><strong>Setup Time</strong></td><td>Weeks of development</td><td>Hours to deploy</td></tr><tr><td><strong>Broker Switching</strong></td><td>Rewrite everything</td><td>Change one config</td></tr><tr><td><strong>Testing</strong></td><td>Build your own sandbox</td><td>Analyzer Mode ready</td></tr><tr><td><strong>Charting</strong></td><td>Buy or build</td><td>Built in with 90+ indicators</td></tr><tr><td><strong>Options Desk</strong></td><td>Build from scratch</td><td>18 tools included</td></tr><tr><td><strong>Monitoring</strong></td><td>Build dashboards</td><td>Full UI included</td></tr><tr><td><strong>Security</strong></td><td>Implement yourself</td><td>Production-ready</td></tr><tr><td><strong>Maintenance</strong></td><td>You maintain everything</td><td>Community maintained</td></tr><tr><td><strong>Cost</strong></td><td>Your development time</td><td>Free and open source</td></tr></tbody></table><p><strong>Broker APIs give you </strong><em><strong>access</strong></em><strong>.</strong> <strong>Tradeboard gives you </strong><em><strong>infrastructure</strong></em><strong>.</strong></p><p>It doesn&#39;t replace your strategy logic. It <strong>amplifies</strong> it with the ecosystem you need to operate, monitor, test, and scale confidently, and it now gives you a place to trade from directly when you don&#39;t want to write a strategy at all.</p><p>And when you&#39;re ready to switch brokers or expand to multi-broker setups, you&#39;ll already be on <strong>Tradeboard&#39;s unified, broker-agnostic foundation</strong>.</p><hr><p><strong>Previous</strong>: 01 - What is Tradeboard</p><p><strong>Next</strong>: 03 - Key Concepts</p>`,91)])])}const b=a(d,[["render",s]]);export{m as __pageData,b as default};
